// Exact views of the six owner-selected C01 designs; no new character identities.
const xs=[135,420,685,970,1255,1520];
export const CHARACTERS=xs.map((x,i)=>({id:`c01-${i+1}`,name:`Character ${i+1}`,description:['Teal jacket, dark hair and dark trousers','Cream sweater, brown hair in a bun and blue jeans','Blue hoodie, curly dark hair and dark trousers','Dark jacket, black bob and olive trousers','Grey vest, blond hair, glasses and dark trousers','Green jacket, long curly hair and cream trousers'][i],front:{x,y:158,w:200,h:323},back:{x,y:490,w:200,h:314}}));
export const characterById=id=>CHARACTERS.find(c=>c.id===id)||null;
export function characterArt(id,{back=false,x=0,y=0,width=100,height=162,extra=''}={}){const c=characterById(id);if(!c)return'';const b=back?c.back:c.front,clip=`avatar-${c.id}-${back?'back':'front'}-${width}-${height}`;return `<svg class="character-art" data-character="${c.id}" x="${x}" y="${y}" width="${width}" height="${height}" viewBox="${b.x} ${b.y} ${b.w} ${b.h}" preserveAspectRatio="xMidYMax meet" overflow="hidden" ${extra}><defs><clipPath id="${clip}" clipPathUnits="userSpaceOnUse"><rect x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}"/></clipPath></defs><image clip-path="url(#${clip})" href="assets/world/characters-c01.png" width="1774" height="887"/></svg>`;}
const buildingBounds=[{x:30,y:130,w:550,h:305},{x:615,y:95,w:555,h:345},{x:1210,y:130,w:540,h:310},{x:40,y:475,w:535,h:329},{x:615,y:478,w:550,h:326},{x:1210,y:480,w:540,h:324}];
export function buildingArt(index,x,y,width,height){const b=buildingBounds[index-1],col=(index-1)%3,bottom=index>3?520:150,right=col*590+180,clip='building-'+index;return `<svg class="building-art" x="${x}" y="${y}" width="${width}" height="${height}" viewBox="${b.x} ${b.y} ${b.w} ${b.h}" preserveAspectRatio="xMidYMax meet" overflow="hidden"><defs><clipPath id="${clip}" clipPathUnits="userSpaceOnUse"><rect x="${b.x}" y="${bottom}" width="${b.w}" height="${b.y+b.h-bottom}"/><rect x="${Math.max(b.x,right)}" y="${b.y}" width="${b.x+b.w-Math.max(b.x,right)}" height="${Math.max(0,bottom-b.y)}"/></clipPath></defs><image clip-path="url(#${clip})" href="assets/world/buildings-h01.png" width="1774" height="887"/></svg>`;}
